    html=urllib.request.urlopen(req, timeout=40).read().decode('utf-8','ignore')
    m=re.search(r'ytInitialPlayerResponse\s*=\s*({.+?});', html)
    d=json.loads(m.group(1))
    vd=d.get('videoDetails',{})
